insert into data_layer_runs (layer_id, source, source_url, license, record_count, notes) values ($q$restricoes_rmsp$q$, $q$avare$q$, $q$https://avare.siscam.com.br/arquivo?Id=200261 (Lei 2.165/2017) ; https://avare.siscam.com.br/arquivo?Id=228181 (Lei 2.294/2019)$q$, $q$Atos oficiais de Avaré: domínio público (Lei 9.610/1998 art. 8º IV). Polígono do centro nobre pelos cruzamentos do OpenStreetMap (ODbL 1.0, © colaboradores do OSM). Limite municipal dos registros revogados: IBGE (dados públicos).$q$, 3, $q$Uma regra vigente: Lei 2.165/2017, art. 4º (centro nobre, caminhão com capacidade de carga acima de 4.500 kg, a qualquer hora; carga e descarga só 00h–10h). Os arts. 1º e 2º (PBT > 25 t nas vias urbanas e > 45 t nas AVRs) foram revogados pela Lei 2.294/2019. Pendente: Dec. 360/1996 ('Disciplina o tráfego de veículos'), não lido.$q$);
